import sys, json

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def array_to_list(arr):
    head = tail = None
    for v in arr:
        n = ListNode(v)
        if head is None:
            head = tail = n
        else:
            tail.next = n
            tail = n
    return head

def list_to_array(node):
    out = []
    while node:
        out.append(node.val)
        node = node.next
    return out

