#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* arrayToList(vector<int>& arr) {
    ListNode *head = nullptr, *tail = nullptr;
    for (int v : arr) {
        ListNode* n = new ListNode(v);
        if (!head) head = tail = n; else { tail->next = n; tail = n; }
    }
    return head;
}
vector<int> listToArray(ListNode* node) {
    vector<int> out;
    while (node) { out.push_back(node->val); node = node->next; }
    return out;
}
vector<int> parseIntArray(const string& s) {
    vector<int> result; string num;
    for (char c : s) {
        if (c=='['||c==']'||c==',') { if (!num.empty()) { result.push_back(stoi(num)); num.clear(); } }
        else if (!isspace((unsigned char)c)) num += c;
    }
    if (!num.empty()) result.push_back(stoi(num));
    return result;
}

